import { describe, expect, it } from 'vitest'

import { PostgresStore } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'

/**
 * Substitutes for the database, recording what was asked of it and answering
 * with rows a test supplies. The seam exists so the store — the statements it
 * runs, what it sends as a parameter, and how it reads what comes back — is
 * exercised without a database to connect to.
 */
class StubQueries implements Queries {
  readonly asked: { sql: string; parameters?: unknown[] }[] = []

  constructor(
    private readonly answer:
      | Record<string, unknown>[]
      | ((sql: string) => Record<string, unknown>[]) = [],
  ) {}

  async run(sql: string, parameters?: unknown[]): Promise<Record<string, unknown>[]> {
    this.asked.push({ sql, parameters })
    return typeof this.answer === 'function' ? this.answer(sql) : this.answer
  }
}

