  readonly calls: { tool: string; args: Record<string, unknown> }[] = []

  constructor(private readonly answers: Record<string, ToolResult>) {}

  async call(tool: string, args: Record<string, unknown>): Promise<ToolResult> {
    this.calls.push({ tool, args })

