describe('writing a Reference Document', () => {
  // Not an oversight. A document the agent could write is a document it could
  // author in the style the Rules exist to catch and then read back as
  // authority, which is the same reason it cannot reload a Rule.
  it.each(['POST', 'PUT', 'DELETE'] as const)('is not reachable over the API (%s)', async (method) => {
    const app = serving(['roaming', roaming])

    const response = await app.inject({
      method,
      url: method === 'POST' ? '/reference-documents' : '/reference-documents/roaming',
      payload: method === 'DELETE' ? undefined : roaming,
    })

    expect(response.statusCode).toBe(404)
  })
})

